    const ToolFinder = ({activeTool,onChoose,openRequest=0}) => {
      const [open,setOpen]=useState(false);
      const [query,setQuery]=useState("");
      const [category,setCategory]=useState("all");
      const toggleRef=useRef(null);
      useEffect(()=>{if(openRequest){setOpen(true);setQuery("");setCategory("all");}},[openRequest]);
      useEffect(()=>{if(open&&openRequest)document.getElementById("tool-finder-query")?.focus();},[open,openRequest]);
      const results=useMemo(()=>FinclarToolNavigation.find(TOOLS,CATEGORIES,query,category),[query,category]);
      const currentCategory=CATEGORIES.find(c=>c.tools.includes(activeTool));
      const choose=key=>{setOpen(false);setQuery("");setCategory("all");onChoose(key);};
      return <section className="tool-finder" aria-label="Calculator chooser">
        <button type="button" ref={toggleRef} className="tool-finder-toggle" aria-expanded={open} aria-controls="tool-finder-body" onClick={()=>setOpen(!open)}>
          <span className="tool-finder-current"><small>{currentCategory.label} · Current calculator</small><strong>{TOOLS[activeTool].label}</strong></span>
          <span className="tool-finder-action">{open?"Close chooser":"Find or change calculator"}<svg className="tool-finder-chevron" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="m5 7 5 5 5-5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/></svg></span>
        </button>
        <div id="tool-finder-body" className="tool-finder-body" hidden={!open} onKeyDown={e=>{if(e.key==="Escape"){e.preventDefault();setOpen(false);toggleRef.current?.focus();}}}>
          {open&&<>
            <div className="tool-finder-search"><label htmlFor="tool-finder-query">Search calculators by name or section</label><div className="tool-finder-search-row">
              <input id="tool-finder-query" type="search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="e.g. HRA, GST, 194IA, EMI" autoComplete="off" aria-controls="tool-finder-results"/>
              {query&&<button type="button" className="tool-finder-clear" onClick={()=>{setQuery("");document.getElementById("tool-finder-query")?.focus();}}>Clear</button>}
            </div></div>
            <div className="cats" role="group" aria-label="Filter calculators by category">
              <button type="button" className={category==="all"?"active":""} aria-pressed={category==="all"} onClick={()=>setCategory("all")}>All calculators · {Object.keys(TOOLS).length}</button>
              {CATEGORIES.map(c=><button type="button" key={c.k} className={category===c.k?"active":""} aria-pressed={category===c.k} onClick={()=>setCategory(c.k)}>{c.label} · {c.tools.length}</button>)}
            </div>
            <p className="tool-finder-count" role="status" aria-live="polite" aria-atomic="true">{results.length} {results.length===1?"calculator":"calculators"} found{category!=="all"?` in ${CATEGORIES.find(c=>c.k===category).label}`:" across all categories"}. Choose one to open it.</p>
            <div id="tool-finder-results" className="tool-finder-results">
              {results.map(item=><button type="button" key={item.key} className="tool-finder-result" aria-current={activeTool===item.key?"true":undefined} onClick={()=>choose(item.key)}><span>{item.label}<small>{item.category}{activeTool===item.key?" · Open now":""}</small></span><span className="tool-finder-arrow" aria-hidden="true">{activeTool===item.key?"✓":"→"}</span></button>)}
            </div>
            {results.length===0&&<p className="tool-finder-empty">No matching calculator. Try a shorter name or section number{category!=="all"?", or choose All calculators":""}.</p>}
          </>}
        </div>
      </section>;
    };

    const App = () => {
      // Deep-link: ?tool=<key> or #<key> takes precedence over localStorage.
      // Lets other site pages link e.g. toolkit.html?tool=sec112a or toolkit.html#it.
      const __deepLink = (() => {
        try {
          const q = window.CA_TOOL || new URLSearchParams(location.search).get("tool");
          if (q && TOOLS[q]) return q;
          const h = (location.hash || "").replace(/^#/, "");
          if (h && TOOLS[h]) return h;
        } catch {}
        return null;
      })();
      const __deepLinkCat = __deepLink ? (CATEGORIES.find(c => c.tools.includes(__deepLink))?.k || null) : null;
      const [cat, setCat] = useState(() => { try { return __deepLinkCat || localStorage.getItem("finclar.cat") || "tax"; } catch { return __deepLinkCat || "tax"; } });
      const [tool, setTool] = useState(() => { try { return __deepLink || localStorage.getItem("finclar.tool") || "it"; } catch { return __deepLink || "it"; } });
      useEffect(()=>{ try { localStorage.setItem("finclar.cat", cat); localStorage.setItem("finclar.tool", tool); } catch {} },[cat,tool]);
      // Hash navigation while page is open — supports SPA-style hash changes
      useEffect(() => {
        const onHash = () => {
          const h = (location.hash || "").replace(/^#/, "");
          if (h && TOOLS[h]) {
            const c = CATEGORIES.find(cc => cc.tools.includes(h));
            if (c) setCat(c.k);
            setTool(h);
          }
        };
        window.addEventListener("hashchange", onHash);
        return () => window.removeEventListener("hashchange", onHash);
      }, []);

      const activeCat = CATEGORIES.find(c=>c.k===cat) || CATEGORIES[0];
      const activeTool = activeCat.tools.includes(tool) ? tool : activeCat.tools[0];
      const Comp = TOOLS[activeTool].comp;
      const [navigationRequest,setNavigationRequest]=useState(0);
      const [finderRequest,setFinderRequest]=useState(0);
      const calculatorRef=useRef(null);
      const chooseTool=key=>{
        const nextCategory=CATEGORIES.find(c=>c.tools.includes(key));
        if(!nextCategory||!TOOLS[key]) return;
        if(window.CA_TOOL&&key!==window.CA_TOOL){location.href="/tools/"+key+"/";return;}setCat(nextCategory.k);setTool(key);setNavigationRequest(n=>n+1);
      };
      useEffect(()=>{
        if(!navigationRequest) return;
        calculatorRef.current?.focus({preventScroll:true});
        calculatorRef.current?.scrollIntoView({block:"start",behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"instant":"smooth"});
      },[navigationRequest]);


      // Tax year selection — one source of truth for every tool. Persisted through
      // useToolState, so it survives reloads and travels inside shared ?s= URLs.
      const [yearKey, setYearKey] = useToolState("global.taxyear", DEFAULT_TAX_YEAR);
      // AY 2025-26 is only offered on tools whose figures all come from tax-rules.json;
      // elsewhere a stored AY 2025-26 choice falls back to AY 2026-27 with a visible note.
      const fallback = yearKey === "AY2025-26" && !RULES_DRIVEN.has(activeTool);
      const effKey = fallback ? "AY2026-27" : (TAX_YEARS[yearKey] ? yearKey : DEFAULT_TAX_YEAR);
      __ruleYear = effKey;
      const y = yearOf(effKey);
      const yearCtx = React.useMemo(() => ({ y, setYear: setYearKey, tool: activeTool, fallback }), [effKey, activeTool, fallback]);

      return (
        <TaxYearCtx.Provider value={yearCtx}>
          <main id="main" className="container">
            <ToolFinder activeTool={activeTool} onChoose={chooseTool} openRequest={finderRequest}/>

            {/* Floating quick-action bar (share / save scenario / print / clear) */}
            <QuickActionBar activeTool={activeTool}/>

            {/* Print-only header — rendered on PDF/print export */}
            <div className="print-header">
              <h1>{TOOLS[activeTool].label}</h1>
              <div className="ph-meta">
                <div><strong>Generated</strong> {new Date().toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"})}</div>
                <div>casaabdulrahim.in/tools/{activeTool}/</div>
                <div>{y.label} · {y.act}</div>
              </div>
            </div>

            <section ref={calculatorRef} id="active-calculator" className="active-calculator" tabIndex={-1} aria-label={TOOLS[activeTool].label+" calculator"}><Comp key={effKey}/></section>

            <div className="print-footer">
              <div><strong>CA S. A. Abdul Rahim</strong> · Chartered Accountant · Adyar, Chennai</div>
              <div>Estimate for the inputs shown. General information only. Not professional advice.</div>
            </div>
          </main>

          <div className="fa-badge">{activeTool === "gstrlf" ? `GST · FY ${y.fy}` : `${y.faShort} · ${y.label}`}</div>
          <div id="sr-announce" className="sr-announce" role="status" aria-live="polite" aria-atomic="true"/>
        </TaxYearCtx.Provider>
      );
    };

    ReactDOM.createRoot(document.getElementById("app")).render(<App/>);
  
